import os
from typing import Any, Iterable, Mapping, Sequence

import requests

ELEVENLABS_API_URL = "https://api.elevenlabs.io/v1/text-to-speech"
ELEVENLABS_VOICE_ID = os.getenv("ELEVENLABS_VOICE_ID", "21m00Tcm4TlvDq8ikWAM")
ELEVENLABS_MODEL_ID = os.getenv("ELEVENLABS_MODEL_ID", "eleven_turbo_v2_5")
ELEVENLABS_API_KEY = os.getenv("ELEVENLABS_API_KEY")


def _iter_results(results: Any) -> Iterable[str]:
    if results is None:
        return []
    if isinstance(results, str):
        return [results]
    if isinstance(results, Mapping):
        for key in ("title", "snippet", "summary", "text", "content"):
            value = results.get(key)
            if isinstance(value, str) and value.strip():
                return [value]
        return [str(results)]
    lines = []
    if isinstance(results, Sequence):
        for item in results:
            if isinstance(item, Mapping):
                title = item.get("title") or item.get("name") or item.get("source")
                snippet = item.get("snippet") or item.get("summary") or item.get("text") or item.get("content")
                if title and snippet:
                    lines.append(f"{title}: {snippet}")
                elif snippet:
                    lines.append(str(snippet))
                elif title:
                    lines.append(str(title))
                else:
                    lines.append(str(item))
            else:
                lines.append(str(item))
    else:
        lines.append(str(results))
    return lines


def build_spoken_brief(results: Any, query: str | None = None) -> str:
    items = [line.strip() for line in _iter_results(results) if line and str(line).strip()]
    if query:
        intro = f"Here is a brief update for your search about {query.strip()}."
    else:
        intro = "Here is a brief update from the retrieved search results."
    if not items:
        return intro + " No relevant results were found."
    joined = " ".join(items[:5])
    return f"{intro} {joined}"


def generate_spoken_brief_audio(
    results: Any,
    query: str | None = None,
    voice_id: str | None = None,
    model_id: str | None = None,
    api_key: str | None = None,
    output_path: str | None = None,
) -> bytes:
